import FeatureSectionV4 from "./feature-section-v4"

export default function Page() {
  return <FeatureSectionV4 />
}

.fsv4-grid {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.75rem;
}

@media (min-width: 640px) {
  .fsv4-grid {
    gap: 0.85rem;
  }
}

@media (min-width: 1024px) {
  .fsv4-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.9rem;
  }
}

.fsv4-cell {
  min-width: 0;
}

.fsv4-card {
  display: flex;
  flex-direction: column;
  min-height: 17rem;
  gap: 0;
  padding: 0;
}

@media (min-width: 640px) {
  .fsv4-card {
    min-height: 20rem;
  }
}

@media (min-width: 1024px) {
  .fsv4-card {
    min-height: 22rem;
  }
}

.fsv4-card-header[data-slot="card-header"] {
  background: transparent;
  border-radius: 0;
}

.fsv4-card-title[data-slot="card-title"] {
  margin: 0;
  line-height: 1.28;
  letter-spacing: -0.015em;
  min-height: calc(1.03rem * 1.28 * 2);
  text-transform: uppercase;
  font-size: 1.03rem;
  font-weight: 600;
}

.fsv4-points {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 0.22rem;
  color: #c8cccc;
  font-family: var(--font-mono, ui-monospace, monospace);
  text-transform: uppercase;
  font-size: 0.73rem;
  line-height: 1.5;
  letter-spacing: 0.025em;
}

.fsv4-points li {
  position: relative;
  padding-left: 0.92rem;
}

.fsv4-points li::before {
  content: "✶";
  position: absolute;
  left: 0;
  top: 0;
  color: #cfd3d3;
}

export type FeatureDefinition = {
  id: "cognitive-ai" | "global-reach" | "limitless-growth"
  labelPrimary: string
  labelSecondary: string
  title: string
  points: [string, string]
}

export const featureSectionItems: FeatureDefinition[] = [
  {
    id: "cognitive-ai",
    labelPrimary: "AI",
    labelSecondary: "Intelligence",
    title: "Cognitive AI Engine",
    points: ["Learns from every interaction", "Surfaces insights instantly"],
  },
  {
    id: "global-reach",
    labelPrimary: "Global",
    labelSecondary: "Scale",
    title: "Planetary-Scale Reach",
    points: ["Deploys across every region", "Connects teams worldwide"],
  },
  {
    id: "limitless-growth",
    labelPrimary: "Growth",
    labelSecondary: "Ambition",
    title: "Reach Beyond Limits",
    points: ["Built for what's next", "Grows with your vision"],
  },
]

/* feature-section v4 — section shell */

.fsv4-section {
  color: var(--foreground);
}
